using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Newtonsoft.Json;
public static class B1Catalog {
 public static object Run(){var list=new List<object>();foreach(var p in AssetDatabase.FindAssets("t:Model",new[]{"Assets/Afrer_Seconds/05.Model/Props"}).Select(AssetDatabase.GUIDToAssetPath)){var n=Path.GetFileNameWithoutExtension(p);if(!new[]{"SF_","SC_","BS_","BO_","LB_","CP_","ID_","SD_","LP_","B1_","P03_","BF_","BX_","OD_"}.Any(n.StartsWith)||n.Contains("_L0")||n.Contains("_L1"))continue;var go=AssetDatabase.LoadAssetAtPath<GameObject>(p);var rs=go.GetComponentsInChildren<Renderer>();if(rs.Length==0)continue;var b=new Bounds();bool first=true;foreach(var r in rs){if(first){b=r.bounds;first=false;}else b.Encapsulate(r.bounds);}list.Add(new{name=n,asset=p,size=new[]{b.size.x,b.size.y,b.size.z},center=new[]{b.center.x,b.center.y,b.center.z},triangles=go.GetComponentsInChildren<MeshFilter>().Sum(m=>m.sharedMesh?Enumerable.Range(0,m.sharedMesh.subMeshCount).Sum(i=>(long)m.sharedMesh.GetIndexCount(i)/3):0)});}
 var h=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B1_FullFloor/catalog.json"));File.WriteAllText(h,JsonConvert.SerializeObject(list,Formatting.Indented));return new{models=list.Count};}
}
